const nowTR = new Date(
  new Date().toLocaleString("en-US", { timeZone: "Europe/Istanbul" })
);

const mm = String(nowTR.getMonth() + 1).padStart(2, "0");
const dd = String(nowTR.getDate()).padStart(2, "0");

return [{
  today_mmdd: `${mm}-${dd}`
}];

return [
  {
    json: {
      full_name_email_list: items.map(i => ({
        full_name: i.json.full_name,
        email: i.json.email,
        avatar_url: i.json.avatar_url
          ? i.json.avatar_url.trim().replace(/\s+/g, '')
          : null
      }))
    }
  }
];

const targetDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
  .toISOString()
  .slice(5,10); // MM-DD

return items.map(item => ({
  json: {
    ...item.json,
    target_mmdd: targetDate
  }
}));

const result = [];

for (const item of items) {
  const birth = new Date(item.json.birth_date);
  const mm = String(birth.getMonth() + 1).padStart(2, '0');
  const dd = String(birth.getDate()).padStart(2, '0');
  const birth_mmdd = `${mm}-${dd}`;

  if (birth_mmdd === item.json.target_mmdd) {
    result.push({
      json: {
        ...item.json,

        x_name: item.json.full_name,
        x_birth_date: item.json.birth_date,

        // 🔴 URL TEMİZLEME (satır sonu + boşluk TAMAMEN gider)
        x_avatar_url: item.json.avatar_url
          ? item.json.avatar_url
              .replace(/[\r\n]/g, '')   // \n ve \r sil
              .replace(/\s+/g, '')      // boşluk sil
          : null
      }
    });
  }
}

return result;

return items.map(item => {
  const birthDate = item.json.birth_date;
  const targetMMDD = item.json.target_mmdd;

  const mmdd = birthDate.slice(5, 10);

  item.json.isBirthday = (mmdd === targetMMDD);

  return item;
});

const todayMMDD = items[0].json.target_mmdd;

// Doğum günü olan kişiyi bul
const birthday = items.find(
  i => i.json.birth_date?.slice(5, 10) === todayMMDD
);

return items.map(item => ({
  json: {
    // Her alıcı için kendi bilgiler
    receiver_name: item.json.full_name,
    email: item.json.email,

    // Doğum günü olan kişiye ait ortak bilgiler
    birthday_person_name: birthday
      ? birthday.json.full_name
      : null,

    birthday_avatar_url: birthday
      ? birthday.json.avatar_url
      : null,

    // ✅ Doğum günü tarihi (YYYY-MM-DD formatında gelir)
    birthday_date: birthday
      ? birthday.json.birth_date
      : null
  }
}));

// ⚠️ items = önceki node'dan gelen TÜM kayıtlar

// 1. Yeni eklenen kısım: Toplam sayıyı hesaplar
const dogum_gunu_sayisi = items.filter(item => item.json.birthday_person_name).length;

return items
  // sadece doğum günü olanlar (birthday_person_name varsa)
  .filter(item => item.json.birthday_person_name)

  // n8n formatı: HER item için { json: {...} }
  .map(item => ({
    json: {
      ...item.json,   // 🔒 HER ŞEY AYNEN KALSIN (Senin kodun)

      // 2. Yeni eklenen kısım: Sayıyı verinin içine tanımlar
      kisi_sayisi: dogum_gunu_sayisi 
    }
  }));

// 🔹 Merge’den gelen TÜM item’ları tek JSON’da birleştir
const base = items.reduce((acc, item) => {
  return { ...acc, ...item.json };
}, {});

// 🔹 Doğum günü olan kişinin adı
const birthdayName = base.birthday_person_name;

// 🔹 Tüm isim listesi
const list = base.full_name_email_list || [];

// 🔹 Aynı isimdekiler (doğum günü sahibi)
const same_name_list = list.filter(
  i => i.full_name === birthdayName
);

// 🔹 Farklı isimdekiler
const different_name_list = list.filter(
  i => i.full_name !== birthdayName
);

// 🔹 TEK item döndür (n8n kuralı)
return [
  {
    json: {
      ...base,              // ✅ birthday_date ARTIK KAYBOLMAZ
      same_name_list,
      different_name_list
    }
  }
];

// Farklı isimdekiler (mail gidecek kişiler)
const differentList = $json.different_name_list || [];

// Ortak bilgiler (doğum günü sahibinden)
const birthdayAvatarUrl = $json.birthday_avatar_url || null;
const birthdayPersonName = $json.birthday_person_name || null;
const birthdayDate = $json.birthday_date || null;

// Her kişiyi AYRI item olarak çıkar
return differentList.map(person => ({
  json: {
    full_name: person.full_name,
    email: person.email,
    birthday_avatar_url: birthdayAvatarUrl,
    birthday_person_name: birthdayPersonName,
    birthday_date: birthdayDate
  }
}));

const data = $json;

const avatarRaw = data.avatar_public_id || "";
const avatarClean = avatarRaw.replace(/^v\d+\//, "");

const bg = data.background_public_id || "HatirlatmaKarti_jdjfuq";

const name = encodeURIComponent(data.birthday_person_name || "");
const d = new Date(data.birthday_date);
const months = ["Ocak","Şubat","Mart","Nisan","Mayıs","Haziran","Temmuz","Ağustos","Eylül","Ekim","Kasım","Aralık"];
const dateText = encodeURIComponent(
  `${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`
);


const cloud = "dtivezty8";

const card_url =
  `https://res.cloudinary.com/${cloud}/image/upload/` +
  `l_image:${avatarClean},c_fill,w_352,h_352,r_max,bo_22px_solid_rgb:4A5FBF,g_center,y_-165/` +
  `l_text:Arial_50_bold:${name},co_rgb:4A5FBF,g_south,y_320/` +
  `l_text:Arial_46:${dateText},co_rgb:4A5FBF,g_south,y_273/` +
  `${bg}.png`;

// ⚠️ ARRAY YOK
return {
  ...data,
  avatar_clean_id: avatarClean,
  card_url
};

const fullName = $json.full_name;

// Kelimelere ayır
const parts = fullName.trim().split(/\s+/);

// Varsayılanlar
let brokenName = fullName;
let fontSize = 42;
let nameY = 0;

// En az 3 kelime varsa ilk iki kelimeyi kontrol et
if (parts.length >= 3) {
  const firstTwo = `${parts[0]} ${parts[1]}`;

  // İlk iki kelime + boşluk 15 karakterden uzunsa kır
  if (firstTwo.length > 15) {
    const firstLine = firstTwo;

    // ⬇⬇⬇ SAĞA KAYDIRMA (3 BOŞLUK)
    const secondLine = "          " + parts.slice(2).join(" ");

    brokenName = `${firstLine}%0A${secondLine}`;
    nameY = -15;
  }
}

// SADECE görselde kullanılacak alanlar
return {
  broken_name: brokenName,
  name_font_size: fontSize,
  name_y: nameY
};

